      "passages": [
        {
          "locator": "normal-web search result: abstract and discussion",
          "text": "The paper reports three chronically implanted participants, parallel speech and gesture decoders, restricted vocabularies, and a proof-of-concept avatar interface."
        },
        {
          "locator": "normal-web search result: discussion",
          "text": "Models trained only on isolated attempts did not fully generalize to simultaneous attempts; the authors call for larger cohorts, larger repertoires and other recording methods."
        }
      ]
    },
    {
      "id": "nih-release-20260914",
      "url": "https://www.nih.gov/news-events/news-releases/neuroprosthesis-paralysis-enables-simultaneous-speech-body-language",
      "publisherType": "official-funder-release",
      "rawCapture": {
        "path": "operations/product-stewards/newsstand/editorial-intake/2026-09-14-nature-new-leads-captures/primary-and-nih-normal-web-open.raw.json",
        "sha256": "292969532bb0ca38d8f60e80b40c1c50383ecf3663f9f689b060b88ea97a133e"
      },
      "passages": [
        {
          "locator": "normal-web open lines 16-27",
          "text": "NIH reports that the study used three patients, translated two participants\u2019 activity into a full-body avatar, and used a wired system connecting implanted sensors to external processing units."
        }
      ]
    }
  ],
  "sourceSafetyLimit": "A single normal-web open of the Nature primary article subsequently returned a non-retryable identity-provider redirect. No retry or alternate transport was used. The preserved normal-web search result is the permitted primary-source content used here.",
  "claimBoundary": "Report the paper as a research proof of concept for people with severe paralysis. Do not claim a consumer product, clinical availability, restored speech, or improved health outcomes."
